import{_ as e,o as r,c as d,a2 as o}from"./chunks/framework.BaXgE4DV.js";const h=JSON.parse('{"title":"출시 준비 체크리스트","description":"","frontmatter":{},"headers":[],"relativePath":"operations/compliance.md","filePath":"operations/compliance.md","lastUpdated":1791571189000}'),a={name:"operations/compliance.md"};function l(s,t,n,i,p,g){return r(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="출시-준비-체크리스트" tabindex="-1">출시 준비 체크리스트 <a class="header-anchor" href="#출시-준비-체크리스트" aria-label="Permalink to &quot;출시 준비 체크리스트&quot;">​</a></h1><p>iOS·Android 앱 출시와 국내 서비스 운영에 필요한 요건을 정리한 체크리스트입니다. 스토어 정책, 국내 법령, 보안·운영, 접근성 네 영역을 검토했습니다.</p><div class="info custom-block"><p class="custom-block-title">검토 기준</p><ul><li><strong>마지막 검토:</strong> 2026-10-07. 각 요건을 그 시점의 공식 원문(Apple·Google 정책 페이지, 국가법령정보센터)과 대조했습니다.</li><li><strong>상태 갱신:</strong> 2026-10-08, 2단계 코드 기준(배포 예정). 웹에서 동작하는 것은 ✅로 표시했고, 네이티브 앱에서 다시 확인할 부분은 3단계 항목에 있습니다. 3단계 항목은 2026-10-09 앱 코드 기준(실제 기기 확인 전)이며 🔶는 &quot;코드 완료, 기기·제출 확인 남음&quot;입니다. → <a href="/grato-docs/mobile/#release-checklist">iOS·Android 앱: 출시 체크리스트</a></li><li><strong>법률 자문이 아닙니다.</strong> 약관과 처리방침 최종본은 운영자가 확인해야 합니다.</li><li>정책은 자주 바뀌므로 <strong>스토어 제출 직전에 한 번 더 확인합니다.</strong></li></ul></div><h2 id="decisions" tabindex="-1">반영된 결정 <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;반영된 결정 {#decisions}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>결정</th><th>영향</th></tr></thead><tbody><tr><td>서비스 이용 연령 <strong>만 14세 이상</strong></td><td>가입 단계에서 연령을 확인함. 법정대리인 동의 절차는 필요 없음</td></tr><tr><td><strong>AI 글쓰기 기능 제거</strong></td><td>외부 AI로 데이터를 보낼 때의 동의, AI 생성물 표시, 생성형 AI 처리방침 항목이 모두 <strong>해당 없음</strong>이 됨 (<a href="/grato-docs/decisions">결정 기록</a>)</td></tr><tr><td><strong>한국에 먼저 출시</strong></td><td>스토어 판매 국가를 대한민국으로 한정함. GDPR은 해당 없음</td></tr><tr><td><strong>감사 글은 기본 &quot;나만 보기&quot;</strong></td><td>다른 사람에게 보이는 글은 작성자가 Circle 공유나 링크 공개를 직접 고른 것뿐. 공개될 수 있는 정보의 사전 안내와 비공개 선택 요건에 도움 (<a href="/grato-docs/decisions#adr-12">결정 기록 #12</a>)</td></tr><tr><td><strong>제안 질문은 사전 검토</strong></td><td>사용자가 제안한 질문은 운영자가 선정한 것만 다른 사용자에게 보임. 아래 <a href="#ugc">UGC 메모</a> 참고 (<a href="/grato-docs/decisions#adr-11">결정 기록 #11</a>)</td></tr><tr><td><strong>그 밖의 UGC는 신고·차단·자동 숨김</strong></td><td>Circle 글·공개 글·댓글·이름은 사후 대응. 필터에 걸리면 즉시 숨김 (<a href="/grato-docs/decisions#adr-14">결정 기록 #14</a>)</td></tr><tr><td><strong>계정 삭제는 삭제가 기본, 일부만 익명화</strong></td><td>다른 사용자가 쓰는 선정 질문과 신고 처리 기록만 연결을 끊어 남김 (<a href="/grato-docs/decisions#adr-15">결정 기록 #15</a>)</td></tr></tbody></table><h2 id="legend" tabindex="-1">범례 <a class="header-anchor" href="#legend" aria-label="Permalink to &quot;범례 {#legend}&quot;">​</a></h2><ul><li><strong>우선순위:</strong> 🔴 출시 차단(심사 거절 또는 법 위반) · 🟠 필수 · 🟡 권장</li><li><strong>상태:</strong> ✅ 완료 · 🔶 일부 · ⬜ 미착수</li><li><strong>단계:</strong> <a href="/grato-docs/guide/roadmap">로드맵</a>의 단계. 2 = 스토어 필수 기능, 3 = 앱 포팅, 4 = 제출, 운영 = 콘솔·절차</li></ul><h2 id="blockers" tabindex="-1">🔴 출시 차단 <a class="header-anchor" href="#blockers" aria-label="Permalink to &quot;🔴 출시 차단 {#blockers}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>근거</th><th>상태</th><th>단계</th></tr></thead><tbody><tr><td><strong>Sign in with Apple</strong> 추가. 구글 로그인과 같은 크기·위치로 배치하고, 비공개 릴레이 이메일을 허용함</td><td><a href="https://developer.apple.com/app-store/review/guidelines/#login-services" target="_blank" rel="noreferrer">Apple 4.8</a></td><td>✅ 웹 (<a href="/grato-docs/features/account#providers">계정</a>). 콘솔 설정은 배포 때, 네이티브는 3단계</td><td>2</td></tr><tr><td><strong>앱 안에서 계정 삭제</strong> (모든 개인 데이터 삭제, Apple 토큰 폐기). 웹에서 삭제를 요청할 수 있는 URL도 제공</td><td><a href="https://developer.apple.com/support/offering-account-deletion-in-your-app/" target="_blank" rel="noreferrer">Apple 5.1.1(v)</a>, <a href="https://support.google.com/googleplay/android-developer/answer/13327111" target="_blank" rel="noreferrer">Google Play</a>, 개인정보 보호법 제36·38조</td><td>✅ MyPage › 설정 › 계정 삭제, 안내 URL <code>/account-deletion</code> (<a href="/grato-docs/features/account#deletion">계정 삭제</a>)</td><td>2</td></tr><tr><td><strong>신고·차단·비속어 필터</strong>, 관리자 신고 처리 화면</td><td><a href="https://developer.apple.com/app-store/review/guidelines/#user-generated-content" target="_blank" rel="noreferrer">Apple 1.2</a>, <a href="https://support.google.com/googleplay/android-developer/answer/9876937" target="_blank" rel="noreferrer">Google UGC</a></td><td>✅ (<a href="#ugc">UGC 메모</a>)</td><td>2</td></tr><tr><td><strong>가입할 때 약관 동의(체크)</strong>. 약관에 금지 콘텐츠·이용자 무관용 원칙, 신고 처리 약속(24시간 이내)을 넣음</td><td><a href="https://support.google.com/googleplay/android-developer/answer/9876937" target="_blank" rel="noreferrer">Google UGC</a>, Apple 1.2</td><td>✅ 동의 화면·규칙 확인, 약관 제10·11조 (<a href="/grato-docs/features/account#consent">약관 동의</a>). 시행일은 배포 전에 입력</td><td>2</td></tr><tr><td><strong>처리방침 법정 필수 항목:</strong> 처리 목적, 보유기간, 파기 방법, 정보주체 권리, 보호책임자 연락처, 자동 수집 장치</td><td><a href="https://www.law.go.kr/%EB%B2%95%EB%A0%B9/%EA%B0%9C%EC%9D%B8%EC%A0%95%EB%B3%B4%EB%B3%B4%ED%98%B8%EB%B2%95" target="_blank" rel="noreferrer">개인정보 보호법 제30조</a></td><td>✅ 전면 개정, 항목 누락은 테스트로 확인 (최종 문구는 운영자 확인)</td><td>2</td></tr><tr><td><strong>처리 위탁·국외 이전 공개:</strong> 수탁자(Google Firebase/Cloud), 이전 국가, 항목</td><td>개인정보 보호법 제26조·제28조의8</td><td>✅ 처리방침 5·6항</td><td>2</td></tr><tr><td><strong>네이티브 앱만의 가치:</strong> 웹사이트를 감싸기만 한 앱이 아님을 보여야 함. 네이티브 로그인·푸시·공유, 웹 전용 UI 정리</td><td><a href="https://developer.apple.com/app-store/review/guidelines/#minimum-functionality" target="_blank" rel="noreferrer">Apple 4.2</a></td><td>🔶 네이티브 로그인·푸시·휴대폰 자체 매일 알림·공유 시트·링크로 앱 열기, PWA 배너·인앱 브라우저 경고 숨김 (<a href="/grato-docs/mobile/">앱</a>)</td><td>3</td></tr><tr><td><strong>네이티브 구글 로그인:</strong> 구글 OAuth는 앱 내부 웹뷰에서 차단됨</td><td><a href="https://developers.google.com/identity/protocols/oauth2/policies" target="_blank" rel="noreferrer">Google OAuth 정책</a></td><td>🔶 네이티브 Google·Apple 로그인 (<a href="/grato-docs/decisions#adr-17">결정 기록 #17</a>)</td><td>3</td></tr><tr><td>Firebase SDK <strong>개인정보 매니페스트</strong>와 서명</td><td><a href="https://developer.apple.com/support/third-party-SDK-requirements/" target="_blank" rel="noreferrer">Apple SDK 요건</a></td><td>🔶 앱 <code>PrivacyInfo.xcprivacy</code>, Firebase SDK는 SPM 패키지의 자체 매니페스트. 아카이브 Privacy Report로 확인</td><td>3</td></tr><tr><td><strong>Xcode 26 / iOS 26 SDK</strong>로 빌드</td><td><a href="https://developer.apple.com/news/upcoming-requirements/" target="_blank" rel="noreferrer">Apple 예정 요건</a></td><td>🔶 개발 기기는 Xcode 27. 제출 빌드에서 확인</td><td>3</td></tr><tr><td><strong>Android 16 (API 36)</strong> 타깃</td><td><a href="https://developer.android.com/google/play/requirements/target-sdk" target="_blank" rel="noreferrer">Play 타깃 API</a></td><td>✅ compile·target SDK 36 (<code>android/variables.gradle</code>)</td><td>3</td></tr><tr><td>Google Play <strong>조직 계정</strong> 인증 (D-U-N-S, 웹사이트, 연락처)</td><td><a href="https://support.google.com/googleplay/android-developer/answer/13628312" target="_blank" rel="noreferrer">Play 계정 요건</a></td><td>🔶</td><td>4</td></tr></tbody></table><h3 id="ugc" tabindex="-1">UGC 메모 <a class="header-anchor" href="#ugc" aria-label="Permalink to &quot;UGC 메모 {#ugc}&quot;">​</a></h3><p>다른 사용자에게 보이는 콘텐츠마다 대응 방식이 다릅니다. → <a href="/grato-docs/features/safety">신고·차단과 자동 숨김</a></p><table tabindex="0"><thead><tr><th>콘텐츠</th><th>방식</th><th>요건 대응</th></tr></thead><tbody><tr><td>제안 질문</td><td><strong>사전 검토</strong>: 운영자가 선정한 것만 보임. 제출 때 욕설·연락처 필터, 하루 한도</td><td><a href="/grato-docs/features/questions">질문 제안과 선정</a></td></tr><tr><td>Circle 글, 링크 공개 글, 댓글</td><td><strong>사후 대응</strong>: 신고(사유 7종), 차단, 욕설·혐오 표현 자동 숨김, 운영자 처리(숨기기·삭제·이용 정지)</td><td>신고·차단·필터·운영자 화면</td></tr><tr><td>공개 이름, Circle 이름·설명</td><td>Circle 생성 때 필터로 거절, 바꾼 이름은 필터에 걸리면 운영자 대기열</td><td>필터·운영자 화면</td></tr><tr><td>로그인 없이 보는 공유 페이지</td><td>&quot;신고하기&quot;(고객지원 이메일, 페이지 주소 포함)</td><td>비로그인 신고 경로</td></tr></tbody></table><ul><li><strong>24시간 대응</strong>: 약관에 &quot;모든 신고를 24시간 안에 검토&quot;를 약속하고, 새 신고는 운영자 기기로 바로 푸시합니다. 운영자가 푸시를 받을 수 있게 운영자 계정의 알림을 켜 둡니다(운영 절차).</li><li><strong>차단은 개발자에게도 알림</strong>: 차단하면 운영자 대기열에 낮은 우선순위 신고가 남습니다(Apple 1.2). 차단 확인 창에도 &quot;운영자에게는 검토를 위해 알려요&quot;라고 씁니다.</li><li><strong>무관용 원칙</strong>: 약관 제10조(금지 콘텐츠), 제12조(이용 제한과 이의 신청).</li><li>운영자는 &quot;나만 보기&quot; 글을 볼 수 없습니다. 다른 사람에게 보이지 않는 글은 신고 대상도 아닙니다.</li></ul><h2 id="musts" tabindex="-1">🟠 필수 <a class="header-anchor" href="#musts" aria-label="Permalink to &quot;🟠 필수 {#musts}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>근거</th><th>상태</th><th>단계</th></tr></thead><tbody><tr><td><strong>만 14세 이상 확인</strong> 단계 (가입 경로 전부: 이메일·구글·Apple)</td><td>개인정보 보호법 제22조의2</td><td>✅ 가입 폼·동의 화면, 미만이면 계정 삭제</td><td>2</td></tr><tr><td>공개될 수 있는 정보에 대한 사전 안내와 비공개 선택 방법 (감사 글에는 건강·신념 같은 민감한 내용이 들어갈 수 있음)</td><td>개인정보 보호법 제23조제3항</td><td>✅ 기본 &quot;나만 보기&quot;, Circle 공유·링크 공개 전 민감 정보 안내, 처리방침 7항</td><td>2</td></tr><tr><td>약관을 약관규제법에 맞게 정비 (중요 내용 명시, 일방 변경·면책 조항 정리)</td><td><a href="https://www.law.go.kr/%EB%B2%95%EB%A0%B9/%EC%95%BD%EA%B4%80%EC%9D%98%EA%B7%9C%EC%A0%9C%EC%97%90%EA%B4%80%ED%95%9C%EB%B2%95%EB%A5%A0" target="_blank" rel="noreferrer">약관규제법</a></td><td>✅ 변경 공지 기간, 면책 범위 정리 (최종 문구는 운영자 확인)</td><td>2</td></tr><tr><td>고객지원 URL과 실제 연락처, 앱 안에서 쉽게 찾을 수 있는 문의 경로</td><td><a href="https://developer.apple.com/help/app-store-connect/reference/app-information/platform-version-information" target="_blank" rel="noreferrer">App Store Connect</a></td><td>✅ <code>/support</code>, MyPage › 설정 › 고객 지원</td><td>2</td></tr><tr><td><strong>앱 접근 권한 고지·동의:</strong> 필수와 선택을 구분 (사진, 알림)</td><td><a href="https://www.law.go.kr/%EB%B2%95%EB%A0%B9/%EC%A0%95%EB%B3%B4%ED%86%B5%EC%8B%A0%EB%A7%9D%EC%9D%B4%EC%9A%A9%EC%B4%89%EC%A7%84%EB%B0%8F%EC%A0%95%EB%B3%B4%EB%B3%B4%ED%98%B8%EB%93%B1%EC%97%90%EA%B4%80%ED%95%9C%EB%B2%95%EB%A5%A0" target="_blank" rel="noreferrer">정보통신망법 제22조의2</a></td><td>⬜</td><td>3</td></tr><tr><td>푸시 알림 없이도 앱이 동작해야 하고, 알림에 민감한 내용을 담지 않음. Android 13 이상 알림 권한</td><td><a href="https://developer.apple.com/app-store/review/guidelines/#push-notifications" target="_blank" rel="noreferrer">Apple 4.5.4</a></td><td>🔶 앱: 권한은 버튼을 눌렀을 때만 요청(Android 13+ <code>POST_NOTIFICATIONS</code> 포함), 거부해도 앱 동작, 푸시 채널은 잠금 화면 비공개 (<a href="/grato-docs/mobile/#push">푸시</a>)</td><td>3</td></tr><tr><td>iOS 권한 용도 문구 (Info.plist)</td><td><a href="https://developer.apple.com/app-store/review/guidelines/#data-collection-and-storage" target="_blank" rel="noreferrer">Apple 5.1.1</a></td><td>🔶 카메라, 사진 보관함, 사진 추가 문구(한국어)</td><td>3</td></tr><tr><td>Android <strong>시스템 사진 선택기</strong> 사용 (미디어 읽기 권한 대신)</td><td><a href="https://support.google.com/googleplay/android-developer/answer/14115180" target="_blank" rel="noreferrer">Play 사진·동영상 권한</a></td><td>🔶 미디어 읽기 권한을 선언하지 않음(웹뷰 파일 선택 사용). 기기에서 선택 화면 확인</td><td>3</td></tr><tr><td>Android 16 <strong>edge-to-edge</strong>와 iOS 노치를 고려한 안전 영역 처리</td><td><a href="https://developer.android.com/about/versions/16/behavior-changes-16" target="_blank" rel="noreferrer">Android 16 변경 사항</a></td><td>🔶 앱 전용 안전 영역 CSS(<code>html.native</code>), 상태 표시줄 처리 (<a href="/grato-docs/mobile/#screen">화면 처리</a>)</td><td>3</td></tr><tr><td>Apple <strong>개인정보 라벨</strong>, Google <strong>데이터 보안 양식</strong></td><td><a href="https://developer.apple.com/app-store/app-privacy-details/" target="_blank" rel="noreferrer">Apple</a>, <a href="https://support.google.com/googleplay/android-developer/answer/10787469" target="_blank" rel="noreferrer">Google</a></td><td>⬜</td><td>4</td></tr><tr><td>연령 등급 설문 (Apple 새 질문지), Play 앱 콘텐츠 선언</td><td><a href="https://developer.apple.com/help/app-store-connect/reference/age-ratings-values-and-definitions/" target="_blank" rel="noreferrer">Apple</a>, <a href="https://support.google.com/googleplay/android-developer/answer/9859455" target="_blank" rel="noreferrer">Google</a></td><td>⬜</td><td>4</td></tr><tr><td>심사용 데모 계정, 제출 시점에 동작하는 백엔드</td><td><a href="https://developer.apple.com/app-store/review/guidelines/#app-completeness" target="_blank" rel="noreferrer">Apple 2.1</a></td><td>⬜</td><td>4</td></tr><tr><td><strong>모바일 앱 접근성</strong> (장애인차별금지법): 아래 접근성 항목 전체</td><td>장애인차별금지법 제21조·시행령</td><td>⬜</td><td>2–4</td></tr><tr><td><strong>안전성 확보 조치:</strong> 접근 권한 최소화와 기록, 접속 기록, 관리자 계정 보호</td><td><a href="https://www.law.go.kr/%ED%96%89%EC%A0%95%EA%B7%9C%EC%B9%99/%EA%B0%9C%EC%9D%B8%EC%A0%95%EB%B3%B4%EC%9D%98%EC%95%88%EC%A0%84%EC%84%B1%ED%99%95%EB%B3%B4%EC%A1%B0%EC%B9%98%EA%B8%B0%EC%A4%80" target="_blank" rel="noreferrer">안전성 확보조치 기준</a></td><td>🔶 운영자 조치 기록(<code>adminAuditLogs</code>), 운영자도 &quot;나만 보기&quot; 글 열람 불가</td><td>운영</td></tr><tr><td><strong>유출 대응 절차:</strong> 이용자 72시간 내 통지, 요건 해당 시 신고</td><td>개인정보 보호법 제34조·시행령</td><td>⬜</td><td>운영</td></tr><tr><td><strong>Firestore 백업</strong> (PITR 또는 예약 백업)</td><td><a href="https://firebase.google.com/docs/firestore/backups" target="_blank" rel="noreferrer">Firebase 백업</a></td><td>⬜ 처리방침에 시점 복구(7일)를 적었으므로 배포 전에 켬 (<a href="/grato-docs/operations/deploy#release-phase2">배포</a>)</td><td>운영</td></tr><tr><td><strong>API 키 제한:</strong> 브라우저 키는 Firebase API로 제한, 앱용 키 분리</td><td><a href="https://firebase.google.com/docs/projects/api-keys" target="_blank" rel="noreferrer">Firebase API 키</a></td><td>⬜ 앱도 웹뷰 안에서 웹 키를 쓰므로, HTTP 리퍼러로 제한하면 앱이 막힘 (<a href="/grato-docs/mobile/#sign-in-console">앱 로그인</a>)</td><td>운영</td></tr></tbody></table><h2 id="shoulds" tabindex="-1">🟡 권장 <a class="header-anchor" href="#shoulds" aria-label="Permalink to &quot;🟡 권장 {#shoulds}&quot;">​</a></h2><p><strong>스토어·정책</strong></p><ul><li><s>감사 글 삭제 기능</s> ✅ 2단계 (<a href="/grato-docs/features/gratitudes#delete">감사 글: 삭제</a>)</li><li><s>공개 공유 페이지에 로그인 없이도 신고·삭제를 요청할 수 있는 경로 (정보통신망법 제44조의2)</s> ✅ 공유 페이지의 &quot;신고하기&quot;(이메일), 약관 제11조의 권리 침해 신고·임시 조치</li><li>Play 아동 안전 표준 공개: 앱을 소셜 카테고리로 등록하는 경우 해당</li><li>수출 규정 신고: <code>ITSAppUsesNonExemptEncryption = false</code></li><li>기기 변경 시 로그인 복원: Play, 2027년부터</li></ul><p><strong>보안·운영</strong></p><ul><li><a href="https://firebase.google.com/docs/app-check" target="_blank" rel="noreferrer">App Check</a>: 웹은 reCAPTCHA Enterprise, iOS는 App Attest, Android는 Play Integrity</li><li>Hosting 보안 헤더: HSTS, CSP, X-Content-Type-Options, Referrer-Policy</li><li>Universal Links·App Links 파일: Hosting 설정의 <code>appAssociation</code>과 함께 정리</li><li>운영·개발 Firebase 프로젝트 분리, Crashlytics, 에러·예산 알림</li><li>CI에서 테스트 3종 자동 실행, 의존성 취약점 정리</li><li>이메일 존재 여부 노출 방지, 비밀번호 정책</li><li>프로젝트 삭제 방지(lien), IAM 정리</li><li>업로드 사진의 위치 정보(EXIF) 제거</li></ul><p><strong>접근성·품질</strong> (WCAG 2.2 AA / KWCAG 2.2 기준)</p><ul><li>아이콘 버튼 이름, 입력란 레이블과 오류 안내, 색 대비 4.5:1</li><li>대화상자 의미 구조와 포커스 관리, <code>window.confirm</code>/<code>alert</code>를 앱 내 컴포넌트로 교체 (🔶 삭제·차단·Circle 설정은 <code>ConfirmDialog</code>로 바꿈, 일부 화면은 남음)</li><li>터치 영역 24px 이상(권장 44pt/48dp), 포커스 표시, 화면 전환 시 제목 갱신</li><li>동작 줄이기·글자 크기 확대 대응, 다크 모드 또는 <code>color-scheme: light</code> 명시</li><li>모바일에서 포그라운드 알림을 Service Worker로 표시</li><li>한글 입력 조합 중 Enter 처리</li><li>오프라인·오류·빈 화면을 구분해 안내, 404 화면</li></ul><h2 id="not-applicable" tabindex="-1">해당 없음 <a class="header-anchor" href="#not-applicable" aria-label="Permalink to &quot;해당 없음 {#not-applicable}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>요건</th><th>이유</th></tr></thead><tbody><tr><td>외부 AI로 데이터를 보낼 때의 동의 (Apple 5.1.2(i)), AI 결과물 신고 (Play), AI 기본법 고지·표시, 처리방침 생성형 AI 항목</td><td>AI 기능 제거</td></tr><tr><td>GDPR, EU 대리인</td><td>한국에만 출시</td></tr><tr><td>법정대리인 동의 절차</td><td>만 14세 미만은 가입 불가</td></tr><tr><td>위치정보법</td><td>위치를 수집하지 않음</td></tr><tr><td>전자상거래법 사업자 정보 표시</td><td>무료 서비스, 결제 없음 (유료화하면 다시 검토)</td></tr><tr><td>광고성 정보 전송 동의</td><td>알림은 서비스 안내용이고 광고가 아님 (광고 알림을 도입하면 별도 동의 필요)</td></tr></tbody></table>',24)])])}const f=e(a,[["render",l]]);export{h as __pageData,f as default};
